## Building Web Servers

### Basic Server

```xiom
use xiom.http;

fn main() -> Int {
  let server = http::Server::new();

  server.route("/", |req| {
    return http::Response::ok("Hello, XIOM!");
  });

  server.route("/api/users", |req| {
    let users = get_all_users();
    let json = json::to_string(&users);
    return http::Response::ok(json)
      .header("Content-Type", "application/json");
  });

  server.listen(8080)?;
  return 0;
}
```

### Route Parameters

```xiom
server.route("/api/users/{id}", |req| {
  let user_id: Int = req.param("id")?.parse_int()?;
  let user = find_user(user_id)?;

  match user {
    Some(u) => http::Response::ok(json::to_string(&u)),
    None => http::Response::not_found(),
  }
});
```

### Middleware

```xiom
// Logging middleware
server.use(|req, next| {
  let start = time::now();
  let response = next(req);
  io.println(req.method.to_str() + " " + req.path + " → " +
              response.status.to_str() + " (" +
              (time::now() - start).to_str() + "ms)");
  return response;
});

// Auth middleware
server.use("/api/*", |req, next| {
  match req.header("Authorization") {
    Some(token) if validate_token(token) => next(req),
    _ => http::Response::unauthorized(),
  }
});

// CORS middleware
server.use(|req, next| {
  let mut response = next(req);
  response.header("Access-Control-Allow-Origin", "*");
  return response;
});
```

### Request Handling

```xiom
fn handle_create_user(req: &http::Request) -> http::Response {
  // Parse JSON body
  let body = json::parse(&req.body)?;
  let name = body["name"].as_str()?;
  let email = body["email"].as_str()?;

  // Validate
  if name.len() == 0 || !email.contains("@") {
    return http::Response::bad_request("Invalid name or email");
  }

  // Create user
  let user = create_user(name, email)?;
  return http::Response::created(json::to_string(&user));
}
```

### Response Helper

```xiom
pub type ApiResponse[T] = {
  success: Bool;
  data: Option[T];
  error: Option[Str];
}

fn ok_response[T: Serialize](data: &T) -> http::Response {
  let body = ApiResponse{ success: true, data: Some(data), error: None };
  return http::Response::ok(json::to_string(&body))
    .header("Content-Type", "application/json");
}

fn error_response(message: Str) -> http::Response {
  let body = ApiResponse{ success: false, data: None, error: Some(message) };
  return http::Response::internal_server_error(json::to_string(&body))
    .header("Content-Type", "application/json");
}
```

